/**
 * Generates the hosted MCP's low-level layer (src/generated/hosted/) from schemas/hosted-tools.json.
 * Never edit src/generated by hand. Usage: npm run codegen-hosted (or npm run regen-hosted).
 *
 * - types.ts    : for each tool, the root parameters (Base, without session_id / agent_id / context, which the
 *                 library injects), one args type per action and the "one item of actions" union (label + one action).
 * - tools.ts    : per tool, `call(input, context?)` and one shortcut per action `action(base, args, context?)`.
 * - manifest.ts : list of tools and their actions.
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { compile, type JSONSchema } from "json-schema-to-typescript";

type S = JSONSchema & { properties?: Record<string, S>; required?: string[]; anyOf?: S[]; items?: S };
interface Tool { name: string; description?: string; inputSchema: S }
const { tools, server } = JSON.parse(readFileSync("schemas/hosted-tools.json", "utf8")) as {
  tools: Tool[];
  server: { name: string; version: string };
};

const COMMON = new Set(["session_id", "agent_id", "context"]);
const pascal = (s: string) => s.replace(/(^|[_\-\s]+)([a-z0-9])/gi, (_, __, c: string) => c.toUpperCase());
const camel = (s: string) => pascal(s).replace(/^./, (c) => c.toLowerCase());
const opts = { bannerComment: "", additionalProperties: false, format: false, strictIndexSignatures: true } as const;
const doc = (s: string | undefined, n = 300) => `/** ${(s ?? "").replace(/\*\//g, "*\\/").replace(/\s+/g, " ").trim().slice(0, n)} */`;
const obj = (properties: Record<string, S>, required: string[]): S =>
  ({ type: "object", properties, required: required.filter((r) => r in properties), additionalProperties: false });

const typeChunks: string[] = [];
const fns: string[] = [];
const manifest: Array<{ name: string; root: string[]; actions: string[] | null }> = [];

for (const t of tools) {
  const T = pascal(t.name);
  const props = Object.fromEntries(Object.entries(t.inputSchema.properties ?? {}).filter(([k]) => !COMMON.has(k)));
  const required = (t.inputSchema.required ?? []).filter((r) => !COMMON.has(r));
  // anyOf of { label, action } variants; a single-action tool (asset_tool) has the object directly.
  const items = props.actions?.items as S | undefined;
  const single = items?.properties && Object.keys(items.properties).filter((k) => k !== "label").length === 1 && "label" in items.properties;
  const variants = items?.anyOf ?? (single ? [items!] : undefined);
  const lit = JSON.stringify(t.name);

  if (!variants) {
    manifest.push({ name: t.name, root: Object.keys(props), actions: null });
    typeChunks.push(await compile(obj(props, required), `${T}Input`, opts));
    fns.push(`${doc(t.description)}\nexport const ${camel(t.name)} = (input: T.${T}Input, context?: string) => callHosted(${lit}, input as unknown as Record<string, unknown>, context);`);
    continue;
  }

  const { actions: _a, ...baseProps } = props;
  const baseRequired = required.filter((r) => r !== "actions");
  const hasBase = Object.keys(baseProps).length > 0;
  typeChunks.push(await compile(obj(baseProps, baseRequired), `${T}Base`, opts));
  const members: string[] = [];
  const helpers: string[] = [];
  const names: string[] = [];
  for (const v of variants) {
    const action = Object.keys(v.properties ?? {}).find((k) => k !== "label");
    if (!action) continue;
    names.push(action);
    const A = `${T}${pascal(action)}`;
    const schema = v.properties![action];
    typeChunks.push(await compile({ ...schema, description: undefined }, `${A}Args`, opts));
    members.push(`{ label: string; ${action}: ${A}Args }`);
    const sig = hasBase ? `base: T.${T}Base, args: T.${A}Args, context?: string` : `args: T.${A}Args, context?: string`;
    const base = hasBase ? "...base, " : "";
    helpers.push(`  ${doc(schema.description, 200)}\n  ${camel(action)}: (${sig}) => callHosted(${lit}, { ${base}actions: [{ label: ${JSON.stringify(action)}, ${action}: args }] }, context),`);
  }
  manifest.push({ name: t.name, root: Object.keys(baseProps), actions: names });
  typeChunks.push(`/** One item of \`actions\` for ${t.name}: a label and exactly one action. */\nexport type ${T}Action = ${members.join(" | ")};`);
  typeChunks.push(`export type ${T}Input = ${T}Base & { actions: ${T}Action[] };`);
  fns.push(
    `${doc(t.description)}\nexport const ${camel(t.name)} = {\n` +
      `  /** Raw call: several actions run in order; a failure does not stop the batch (see results[i].error). */\n` +
      `  call: (input: T.${T}Input, context?: string) => callHosted(${lit}, input as unknown as Record<string, unknown>, context),\n` +
      helpers.join("\n") + `\n};`,
  );
}

const header = (what: string) =>
  `// Generated by scripts/codegen-hosted.ts from schemas/hosted-tools.json (${server.name} ${server.version}). Do not edit.\n// ${what}\n`;
mkdirSync("src/generated/hosted", { recursive: true });
writeFileSync("src/generated/hosted/types.ts", header("Tool input types (without session_id / agent_id / context).") + "/* eslint-disable */\n" + typeChunks.join("\n"));
writeFileSync(
  "src/generated/hosted/tools.ts",
  header("Hosted MCP tool wrappers.") + `import { callHosted } from "../../lib/hosted.js";\nimport type * as T from "./types.js";\n\n` + fns.join("\n\n") + "\n",
);
writeFileSync(
  "src/generated/hosted/manifest.ts",
  header("Tool list.") + `export const hostedServerVersion = ${JSON.stringify(server)} as const;\nexport const hostedTools = ${JSON.stringify(manifest, null, 2)} as const;\n`,
);
const nActions = manifest.reduce((n, m) => n + (m.actions?.length ?? 0), 0);
console.log(`codegen-hosted : ${manifest.length} outils, ${nActions} actions, ${typeChunks.length} types.`);
